import type { Model } from "../expand.ts";
import type { Shell } from "../paths.ts";
import { renderFunction } from "./functions.ts";
import { quote } from "./quote.ts";

/** First line of every generated file; also marks files aliaz may overwrite. */
export const GENERATED_HEADER = "# Generated by aliaz. Do not edit.";

const aliasLine = (name: string, command: string, shell: Shell): string => {
  const body = quote(command, shell);
  return shell === "fish" ? `alias ${name} ${body}` : `alias ${name}=${body}`;
};

/** The full text of the sourceable file for one shell. */
export const render = (model: Model, shell: Shell): string => {
  const out = [GENERATED_HEADER, `# Shell: ${shell}`, ""];
  const groups = [
    ...new Set([
      ...model.aliases.map((a) => a.group),
      ...model.functions.map((f) => f.group),
    ]),
  ];
  for (const group of groups) {
    out.push(`# ${group}`);
    for (const a of model.aliases.filter((x) => x.group === group)) {
      if (a.description && a.kind !== "expanded") {
        out.push(`# ${a.name}: ${a.description}`);
      }
      out.push(aliasLine(a.name, a.command, shell));
    }
    for (const f of model.functions.filter((x) => x.group === group)) {
      if (f.description) out.push(`# ${f.name}: ${f.description}`);
      out.push(...renderFunction(f, shell));
    }
    out.push("");
  }
  return out.join("\n");
};
